CREATE TABLE scheduled_job_runs (id varchar(64) PRIMARY KEY,scheduled_job_id varchar(64) NOT NULL,job_code varchar(128) NOT NULL,job_name text NOT NULL,handler varchar(128) NOT NULL,trigger_source varchar(32) NOT NULL,status varchar(32) NOT NULL,request_id varchar(128) NOT NULL,trace_id varchar(128) NOT NULL,started_at timestamp(6) NOT NULL,finished_at timestamp(6) NOT NULL,duration_ms bigint NOT NULL,error_message text NOT NULL,created_at timestamp(6) NOT NULL,created_by text NOT NULL,updated_at timestamp(6) NOT NULL,updated_by text NOT NULL,version bigint NOT NULL,deleted_at timestamp(6) NULL,deleted_by text,KEY scheduled_job_runs_page_idx(scheduled_job_id,started_at,id),KEY scheduled_job_runs_status_idx(status,started_at,id),CONSTRAINT scheduled_job_runs_job_fk FOREIGN KEY(scheduled_job_id) REFERENCES scheduled_jobs(id));
CREATE TRIGGER scheduled_job_runs_audit_bi BEFORE INSERT ON scheduled_job_runs FOR EACH ROW SET NEW.created_at=CURRENT_TIMESTAMP(6),NEW.created_by=NULLIF(TRIM(@app_actor_id),''),NEW.updated_at=CURRENT_TIMESTAMP(6),NEW.updated_by=NULLIF(TRIM(@app_actor_id),''),NEW.version=1,NEW.deleted_by=CASE WHEN NEW.deleted_at IS NULL THEN NULL ELSE NULLIF(TRIM(@app_actor_id),'') END;
CREATE TRIGGER scheduled_job_runs_audit_bu BEFORE UPDATE ON scheduled_job_runs FOR EACH ROW SET NEW.created_at=OLD.created_at,NEW.created_by=OLD.created_by,NEW.updated_at=CURRENT_TIMESTAMP(6),NEW.updated_by=NULLIF(TRIM(@app_actor_id),''),NEW.version=OLD.version+1,NEW.deleted_by=CASE WHEN NEW.deleted_at IS NULL THEN NULL WHEN OLD.deleted_at IS NULL THEN NULLIF(TRIM(@app_actor_id),'') ELSE OLD.deleted_by END;
CREATE TRIGGER scheduled_job_runs_audit_bd BEFORE DELETE ON scheduled_job_runs FOR EACH ROW SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='physical delete is forbidden';
